export function filterNil<T>(): OperatorFunction<T, NonNullable<T>> {
  return source => source.pipe(filter((v): v is NonNullable<T> => v != null));
}

export function debugLifecycle<T>(tag: string): MonoTypeOperatorFunction<T> {
  return source => new Observable<T>(subscriber => {
    console.debug(tag, 'subscribe');
    const sub = source.subscribe(subscriber);
    return () => { console.debug(tag, 'unsubscribe'); sub.unsubscribe(); };
  });
}

it('debounces and keeps only the latest term', () => {
  scheduler.run(({ hot, cold, expectObservable }) => {
    const terms$ = hot('a 100ms b 400ms |');
    const response$ = cold('--r|', { r: ['wynik'] });
    const result$ = terms$.pipe(debounceTime(300), switchMap(() => response$));

    // 'b' emitowane w 401, odpowiedź 2 klatki później, complete w 502
    expectObservable(result$).toBe('403ms r 98ms |', { r: ['wynik'] });
  });
});

