export class TickerComponent {
  private readonly destroyRef = inject(DestroyRef);

  constructor() {
    inject(PriceStream).prices$.pipe(
      switchMap(p => this.enrich(p)),
      takeUntilDestroyed(this.destroyRef),   // ostatni w łańcuchu!
    ).subscribe(p => this.last.set(p));

    const ro = new ResizeObserver(() => this.relayout());
    ro.observe(inject(ElementRef).nativeElement);
    this.destroyRef.onDestroy(() => ro.disconnect());
  }
}

